{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw, ImageOps
im = Image.open('radiograph.jpg').convert('L')

def gridded_zoom(name, box, s=4, step=20, mode='auto'):
    x1,y1,x2,y2 = box
    c = im.crop(box)
    if mode=='auto': c = ImageOps.autocontrast(c, cutoff=1)
    elif mode=='eq': c = ImageOps.equalize(c)
    c = c.resize((c.width*s, c.height*s), Image.LANCZOS).convert('RGB')
    d = ImageDraw.Draw(c)
    for gx in range(x1 - x1%step + step, x2, step):
        cx = (gx-x1)*s
        d.line([(cx,0),(cx,c.height)], fill=(255,60,60), width=1)
        if gx % 50 == 0: d.text((cx+2,2), str(gx), fill=(255,255,0))
    for gy in range(y1 - y1%step + step, y2, step):
        cy = (gy-y1)*s
        d.line([(0,cy),(c.width,cy)], fill=(255,60,60), width=1)
        if gy % 50 == 0: d.text((2,cy+2), str(gy), fill=(255,255,0))
    c.save(f'crops/{name}.png')
    print(name, c.size)

